mapper.select:
SELECT * FROM iot_data_parse_strategy WHERE del_flag = 0
AND name LIKE CONCAT('%', #{name}, '%')
AND source_type = #{sourceType}
AND status = #{status}
AND app_scope = #{appScope}
ORDER BY create_time DESC

mapper.insert:
INSERT INTO iot_data_parse_strategy (name, source_type, description, status, app_scope, script_code, is_preset
    , create_by
    , create_time
    , update_by
    , update_time
) VALUES (#{name}, #{sourceType}, #{description}, #{status}, #{appScope}, #{scriptCode}, IFNULL(#{isPreset}, 0)
    , #{createBy}
    , #{createTime}
    , #{updateBy}
    , #{updateTime}
)

mapper.update:
UPDATE iot_data_parse_strategy
SET name = #{name}, source_type = #{sourceType}, description = #{description},
    status = #{status}, app_scope = #{appScope}, script_code = #{scriptCode}
    , update_by = #{updateBy}
    , update_time = #{updateTime}
WHERE id = #{id}

UPDATE iot_data_parse_strategy SET del_flag = 1
    , update_by = #{updateBy}
    , update_time = #{updateTime}
WHERE id = #{id}

mapper.select:
SELECT * FROM iot_data_parse_strategy WHERE name = #{name} AND del_flag = 0
AND id != #{id}
LIMIT 1
